import os
import pandas as pd
from google import genai
from dotenv import load_dotenv

# 1. Look for the .env file and securely load the variables into memory
load_dotenv()

# 2. Pull the API key from memory instead of hardcoding it
API_KEY = os.environ.get("GEMINI_API_KEY")

if not API_KEY:
    print("❌ Error: GEMINI_API_KEY not found in .env file!")
    exit()

print("🤖 Initializing Secure Cloud AI Incident Responder...")

# 3. Load the security alerts generated by your pipeline
try:
    df_alerts = pd.read_csv('security_alerts.csv')
except FileNotFoundError:
    print("❌ Error: 'security_alerts.csv' not found. Run pipeline.py first!")
    exit()

# 4. Filter for the absolute worst threats (massive data leaks)
critical_hacks = df_alerts[df_alerts['Bytes'] > 1000000]

if critical_hacks.empty:
    print("✅ No critical data leaks found today. System safe.")
    exit()

print(f"🚨 Found critical security breaches. Formatting for AI Analysis...")

# 5. Format the data for the AI
incident_report_data = ""
for index, row in critical_hacks.head(3).iterrows():
    incident_report_data += f"- Time: {row['Timestamp']} | User: {row['User_ID']} | IP: {row['IP']} | Action: {row['Action']} | Data Leaked: {row['Bytes']} bytes\n"

ai_system_instruction = """
ROLE: You are an elite enterprise Cybersecurity AI Agent.
TASK: Analyze the raw server alerts provided below and write a 3-sentence summary for the engineering team.
FORMAT:
- Sentence 1: Identify the primary malicious activity and who did it.
- Sentence 2: Explain the potential business damage (e.g., data exfiltration).
- Sentence 3: Provide an immediate mitigation step (e.g., block the IP, revoke user tokens).
"""

full_llm_prompt = f"{ai_system_instruction}\n\nRAW INCIDENT DATA:\n{incident_report_data}"

# 6. Initialize the live AI Client using your hidden environment key
client = genai.Client(api_key=API_KEY)

print("📡 Sending breach logs to cloud model...")

# 7. Execute the live cloud call
response = client.models.generate_content(
    model="gemini-2.5-flash",
    contents=full_llm_prompt
)

print("\n🔥 --- LIVE AI EXECUTIVE BRIEFING ---")
print(response.text)
print("---------------------------------------")
print("🏁 Incident analysis complete.")